#!/usr/bin/env python3
# Generated by test-lab — blind adversarial evaluation
"""
Integration tests for hack skill delegation features.

Tests that skill paths are correctly resolved and skills can be invoked.
"""
import os
import subprocess
import sys
from pathlib import Path

# dotenv_helper is not invoked here; this generated smoke test only passes
# through an explicit subprocess environment.
GREEN = "\033[0;32m"
RED = "\033[0;31m"
YELLOW = "\033[1;33m"
NC = "\033[0m"  # No Color

SKILL_DIR = Path(__file__).parent.parent  # Go up from tests/ to hack/
CANONICAL_SKILLS = Path.home() / "workspace" / "experiments" / "pi-mono" / ".pi" / "skills"


def run_test(name: str, cmd: list[str], should_succeed: bool = True) -> bool:
    """Run a single test command."""
    print(f"\n[TEST] {name}")
    print(f"  Command: {' '.join(cmd)}")
    
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=10,
            cwd=SKILL_DIR,  # Run from hack/ directory
            env={k: v for k, v in os.environ.items() if k != 'VIRTUAL_ENV'},
        )
        
        if should_succeed:
            if result.returncode == 0:
                print(f"  {GREEN}✓ PASS{NC}")
                return True
            else:
                print(f"  {RED}✗ FAIL{NC}")
                print(f"  stdout: {result.stdout[:200]}")
                print(f"  stderr: {result.stderr[:200]}")
                return False
        else:
            # Test should fail (negative test)
            if result.returncode != 0:
                print(f"  {GREEN}✓ PASS (expected failure){NC}")
                return True
            else:
                print(f"  {RED}✗ FAIL (should have failed){NC}")
                return False
                
    except subprocess.TimeoutExpired:
        print(f"  {YELLOW}⚠ TIMEOUT{NC}")
        return False
    except Exception as e:
        print(f"  {RED}✗ ERROR: {e}{NC}")
        return False


def main():
    """Run all integration tests."""
    print("=" * 60)
    print("Hack Skill Integration Tests")
    print("=" * 60)
    
    tests_passed = 0
    tests_failed = 0
    
    # Test 1: Core tool (should work without skill delegation)
    if run_test(
        "Core tool - tools command",
        ["./run.sh", "tools"],
    ):
        tests_passed += 1
    else:
        tests_failed += 1
    
    # Test 2: Memory integration - recall
    if run_test(
        "Memory integration - recall command",
        ["./run.sh", "recall", "test query"],
    ):
        tests_passed += 1
    else:
        tests_failed += 1
    
    # Test 3: Memory integration - remember
    if run_test(
        "Memory integration - remember command",
        ["./run.sh", "remember", "test knowledge", "--title", "Test"],
    ):
        tests_passed += 1
    else:
        tests_failed += 1
    
    # Test 4: Research delegation - dogpile
    if (CANONICAL_SKILLS / "dogpile" / "run.sh").exists():
        if run_test(
            "Research delegation - dogpile",
            ["./run.sh", "research", "test topic", "--skill", "dogpile"],
        ):
            tests_passed += 1
        else:
            tests_failed += 1
    else:
        print(f"\n{YELLOW}[SKIP] Dogpile skill not found{NC}")
    
    # Test 5: Invalid skill (should fail gracefully)
    if run_test(
        "Error handling - invalid skill",
        ["./run.sh", "research", "topic", "--skill", "nonexistent"],
        should_succeed=False,
    ):
        tests_passed += 1
    else:
        tests_failed += 1
    
    # Test 6: Symbols command (if treesitter available)
    if (CANONICAL_SKILLS / "treesitter" / "run.sh").exists():
        test_file = SKILL_DIR / "hack.py"
        if run_test(
            "Code analysis - symbols extraction",
            ["./run.sh", "symbols", str(test_file)],
        ):
            tests_passed += 1
        else:
            tests_failed += 1
    else:
        print(f"\n{YELLOW}[SKIP] Treesitter skill not found{NC}")
    
    # Test 7: Docker cleanup (ops-docker delegation)
    if (CANONICAL_SKILLS / "ops-docker" / "run.sh").exists():
        if run_test(
            "Docker cleanup delegation",
            ["./run.sh", "docker-cleanup"],
        ):
            tests_passed += 1
        else:
            tests_failed += 1
    else:
        print(f"\n{YELLOW}[SKIP] ops-docker skill not found{NC}")
    
    # Summary
    print("\n" + "=" * 60)
    print("Test Summary")
    print("=" * 60)
    print(f"Passed: {GREEN}{tests_passed}{NC}")
    print(f"Failed: {RED}{tests_failed}{NC}")
    print(f"Total:  {tests_passed + tests_failed}")
    print("=" * 60)
    
    if tests_failed > 0:
        print(f"\n{RED}Some tests failed!{NC}")
        sys.exit(1)
    else:
        print(f"\n{GREEN}All tests passed!{NC}")
        sys.exit(0)


if __name__ == "__main__":
    main()
